<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Landmark, Plus, RotateCcw, WalletCards } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import type { CurrencyUnit } from '../utils/currency'
import { formatMoney, formatMoneyInput, parseMoneyInput } from '../utils/currency'
import { formatDateTime } from '../utils/date'
import { accountingApi, type AccountRecord, type FinancialAccountRecord, type JournalEntryRecord, type PaymentRecord } from '../api/accounting'
const props=defineProps<{currencyUnit:CurrencyUnit;orders:any[];suppliers:any[];purchases:any[];customers:any[]}>();const emit=defineEmits<{notify:[message:string]}>()
const tab=ref('Overview');const accounts=ref<AccountRecord[]>([]);const financial=ref<FinancialAccountRecord[]>([]);const journal=ref<JournalEntryRecord[]>([]);const payments=ref<PaymentRecord[]>([]);const loading=ref(false);const error=ref('');
const form=ref({direction:'incoming',method:'cash',financialAccountId:'FIN-CASH',customerId:'',supplierId:'',targetType:'order',targetId:'',amount:'',notes:''});
const money=(v:number)=>formatMoney(v,props.currencyUnit);const totalAssets=computed(()=>accounts.value.filter(a=>a.type==='asset').reduce((n,a)=>n+a.balanceRial,0));const receivable=computed(()=>accounts.value.find(a=>a.code==='1100')?.balanceRial??0);const payable=computed(()=>accounts.value.find(a=>a.code==='2000')?.balanceRial??0)
async function load(){loading.value=true;try{[accounts.value,financial.value,journal.value,payments.value]=await Promise.all([accountingApi.accounts(),accountingApi.financialAccounts(),accountingApi.journal(),accountingApi.payments()]);if(financial.value[0]&&!financial.value.some(x=>x.id===form.value.financialAccountId))form.value.financialAccountId=financial.value[0].id}catch(e){error.value=String(e)}finally{loading.value=false}}
async function create(){try{const amount=parseMoneyInput(form.value.amount,props.currencyUnit);if(amount===null||amount<=0)throw new Error('Enter a positive Rial amount');const targetAmount=parseMoneyInput(form.value.amount,props.currencyUnit)||0;await accountingApi.createPayment({direction:form.value.direction,method:form.value.method,financialAccountId:form.value.financialAccountId,customerId:form.value.customerId||undefined,supplierId:form.value.supplierId||undefined,amountRial:amount,notes:form.value.notes,allocations:form.value.targetId?[{targetType:form.value.direction==='incoming'?'order':'purchase',targetId:form.value.targetId,amountRial:targetAmount}]:[]});form.value.amount='';form.value.targetId='';await load();emit('notify','Payment posted') }catch(e){emit('notify',String(e))}}
async function reverse(p:PaymentRecord){try{await accountingApi.reversePayment(p.id);await load();emit('notify','Payment reversed')}catch(e){emit('notify',String(e))}}
function targetOptions(){return form.value.direction==='incoming'?props.orders:props.purchases}function targetLabel(x:any){return form.value.direction==='incoming'?`${x.orderNumber} · ${x.customerName||'Walk-in'}`:`${x.purchaseNumber} · ${x.supplierName}`}
</script>
<template><div class="accounting-view"><header class="workspace-heading"><div><p class="eyebrow">Finance / authoritative ledger</p><h1>Accounting</h1><p class="heading-description">Balanced integer-Rial journals, derived balances, and payment history.</p></div><button class="button button-primary" @click="tab='Payments'"><Plus :size="15"/>New payment</button></header><nav class="workspace-tabs"><button v-for="name in ['Overview','Accounts','Journal','Payments']" :key="name" :class="{'is-active':tab===name}" @click="tab=name">{{ name }}</button></nav><div v-if="error" class="accounting-error">{{ error }}</div><section v-if="tab==='Overview'" class="accounting-grid"><SectionPanel title="Ledger overview" subtitle="Current balances are derived from posted journal lines."><div class="accounting-metrics"><div><WalletCards :size="17"/><span>Assets</span><strong>{{ money(totalAssets) }}</strong></div><div><Landmark :size="17"/><span>Receivable</span><strong>{{ money(receivable) }}</strong></div><div><Landmark :size="17"/><span>Payable</span><strong>{{ money(payable) }}</strong></div></div></SectionPanel><SectionPanel title="Recent transactions" subtitle="Immutable posted entries"><div v-if="!journal.length" class="workspace-state">No journal entries yet.</div><div v-for="entry in journal.slice(0,6)" :key="entry.id" class="accounting-row"><span><strong>{{ entry.entryNumber }}</strong><small>{{ entry.description }}</small></span><small>{{ formatDateTime(entry.postedAt) }}</small></div></SectionPanel></section><section v-else-if="tab==='Accounts'" class="panel accounting-table"><header class="panel-header"><div><h2 class="panel-title">Chart of accounts</h2><p class="panel-subtitle">Seeded compact chart with derived balances.</p></div></header><div v-for="a in accounts" :key="a.id" class="accounting-row"><span><strong>{{ a.code }} · {{ a.name }}</strong><small>{{ a.type }}</small></span><strong>{{ money(a.balanceRial) }}</strong></div></section><section v-else-if="tab==='Journal'" class="panel accounting-table"><header class="panel-header"><h2 class="panel-title">Journal / transactions</h2></header><div v-for="entry in journal" :key="entry.id" class="journal-entry"><div class="accounting-row"><span><strong>{{ entry.entryNumber }} · {{ entry.description }}</strong><small>{{ formatDateTime(entry.postedAt) }}</small></span><span>{{ entry.lines.length }} lines</span></div><div v-for="line in entry.lines" :key="line.id" class="journal-line"><span>{{ line.accountId }} · {{ line.memo }}</span><span>{{ line.debitRial?money(line.debitRial):'—' }} / {{ line.creditRial?money(line.creditRial):'—' }}</span></div></div></section><section v-else class="accounting-payments"><SectionPanel title="Post payment" subtitle="Allocate partially or leave a customer/supplier balance unallocated."><form class="payment-form" @submit.prevent="create"><select v-model="form.direction"><option value="incoming">Incoming · customer</option><option value="outgoing">Outgoing · supplier</option></select><select v-model="form.method"><option value="cash">Cash</option><option value="bank_transfer">Bank transfer</option><option value="card">Card</option><option value="check">Check</option><option value="other">Other</option></select><select v-model="form.financialAccountId"><option v-for="a in financial" :key="a.id" :value="a.id">{{ a.name }}</option></select><select v-if="form.direction==='incoming'" v-model="form.customerId"><option value="">Select customer</option><option v-for="x in props.orders.map(o=>({id:o.customerId,name:o.customerName})).filter(x=>x.id)" :key="x.id" :value="x.id">{{ x.name }}</option></select><select v-else v-model="form.supplierId"><option value="">Select supplier</option><option v-for="x in suppliers" :key="x.id" :value="x.id">{{ x.name }}</option></select><select v-model="form.targetType"><option value="order">Order / receivable</option><option value="purchase">Purchase / payable</option></select><select v-model="form.targetId"><option value="">Unallocated balance</option><option v-for="x in targetOptions()" :key="x.id" :value="x.id">{{ targetLabel(x) }}</option></select><input v-model="form.amount" :placeholder="`Amount (${props.currencyUnit})`" inputmode="numeric" @blur="form.amount=formatMoneyInput(parseMoneyInput(form.amount,props.currencyUnit)||0,props.currencyUnit)"/><textarea v-model="form.notes" rows="2" placeholder="Notes"></textarea><button class="button button-primary" type="submit">Post payment</button></form></SectionPanel><SectionPanel title="Payment history" subtitle="Reversible history; no destructive deletion."><div v-if="!payments.length" class="workspace-state">No payments yet.</div><div v-for="p in payments" :key="p.id" class="accounting-row"><span><strong>{{ p.paymentNumber }} · {{ p.direction }}</strong><small>{{ money(p.amountRial) }} · {{ formatDateTime(p.postedAt) }}</small></span><span class="payment-actions"><StatusBadge :label="p.status" :tone="p.status==='posted'?'green':'slate'"/><button v-if="p.status==='posted'" class="text-button" @click="reverse(p)"><RotateCcw :size="14"/>Reverse</button></span></div></SectionPanel></section></div></template>
<style scoped>.accounting-view{min-width:0}.accounting-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(300px,1fr);gap:16px}.accounting-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.accounting-metrics div{display:grid;gap:7px;padding:14px;background:var(--surface-muted);border-radius:9px}.accounting-metrics span,.accounting-row small{color:var(--text-muted);font-size:12px}.accounting-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--border);min-width:0}.accounting-row span:first-child{min-width:0;display:grid;gap:3px}.accounting-row strong,.accounting-row small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.accounting-table,.accounting-payments{display:grid;gap:16px}.journal-entry{border-bottom:1px solid var(--border);padding-bottom:8px}.journal-line{display:flex;justify-content:space-between;gap:12px;padding:6px 12px;color:var(--text-muted);font-size:12px}.payment-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.payment-form input,.payment-form select,.payment-form textarea{min-width:0;width:100%;box-sizing:border-box}.payment-form textarea{grid-column:1/-1}.payment-actions{display:flex;align-items:center;gap:8px}.accounting-error{margin:14px 0;padding:10px;background:var(--danger-soft);color:var(--danger)}@media(max-width:900px){.accounting-grid{grid-template-columns:1fr}.payment-form{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.accounting-metrics{grid-template-columns:1fr}.payment-form{grid-template-columns:1fr}}</style>
